import test from 'node:test'
import assert from 'node:assert'
const wait = ms => new Promise(r => setTimeout(r, ms))
test('integration (slow on purpose: about 10 min)', async t => {
  for (let i = 1; i <= 40; i++) {
    await t.test('scenario ' + i, async () => { await wait(15000); assert.ok(true) })
  }
})

